using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using IdleIntelligence.Runtime;
using Image=UnityEngine.UI.Image;using Text=UnityEngine.UI.Text;using LayoutElement=UnityEngine.UI.LayoutElement;
namespace IdleIntelligence.Editor {
 public static class RefineDesignTwo {
  public static void Apply(GameRuntime game){
   // Alter the existing generated UI asset in place; original art and GUIDs stay intact.
   var sprite=AssetDatabase.LoadAssetAtPath<Sprite>("Assets/IdleIntelligence/Resources/ThemeSurface.asset");var texture=sprite.texture;for(int y=0;y<texture.height;y++)for(int x=0;x<texture.width;x++){float dx=Mathf.Max(2-x,Mathf.Max(x-(texture.width-3),0)),dy=Mathf.Max(2-y,Mathf.Max(y-(texture.height-3),0));texture.SetPixel(x,y,new Color(1,1,1,Mathf.Clamp01(2.5f-Mathf.Sqrt(dx*dx+dy*dy))));}texture.Apply();EditorUtility.SetDirty(texture);var flat=Sprite.Create(texture,sprite.rect,new Vector2(.5f,.5f),100,0,SpriteMeshType.FullRect,new Vector4(4,4,4,4));EditorUtility.CopySerialized(flat,sprite);Object.DestroyImmediate(flat);EditorUtility.SetDirty(sprite);
   var save=game.SaveButton;save.GetComponent<Image>().sprite=null;save.GetComponent<Image>().color=Color.clear;var le=save.GetComponent<LayoutElement>();le.minWidth=le.preferredWidth=54;le.flexibleWidth=0;foreach(var t in save.GetComponentsInChildren<Text>(true))t.gameObject.SetActive(false);var glyph=save.transform.Find("SaveIcon");if(glyph==null){var g=WorkshopUIFactory.Node("SaveIcon",save.transform,typeof(CompactGlyph));var icon=g.GetComponent<CompactGlyph>();icon.Kind=CompactGlyph.Symbol.Save;icon.color=GameTheme.Muted;icon.raycastTarget=false;var rect=icon.rectTransform;rect.anchorMin=rect.anchorMax=new Vector2(.5f,.5f);rect.sizeDelta=new Vector2(19,19);}
   if(save.transform.Find("SaveIcon").GetComponent<CanvasRenderer>()==null)save.transform.Find("SaveIcon").gameObject.AddComponent<CanvasRenderer>();
   var view=game.GetComponent<MobileShell>().Laboratory;var compact=view.transform.Find("ModelTraining");compact.GetComponent<LayoutElement>().minHeight=compact.GetComponent<LayoutElement>().preferredHeight=54;foreach(var b in compact.GetComponentsInChildren<UnityEngine.UI.Button>()){b.GetComponent<Image>().color=GameTheme.Background;foreach(var t in b.GetComponentsInChildren<Text>()){t.fontSize=t.resizeTextMaxSize=12;t.resizeTextMinSize=11;}}
   view.Floating.fontSize=16;view.Floating.rectTransform.sizeDelta=new Vector2(100,28);PrefabUtility.ApplyPrefabInstance(view.gameObject,InteractionMode.AutomatedAction);
